from solution import prime_fib
import pytest
from hypothesis import given, strategies as st


# ---- obviously-correct reference model (written from spec, not from solution) ----

def _ref_is_prime(m: int) -> bool:
    if m < 2:
        return False
    if m % 2 == 0:
        return m == 2
    d = 3
    while d * d <= m:
        if m % d == 0:
            return False
        d += 2
    return True


def _ref_fib(k: int) -> int:
    # standard Fibonacci: F(0)=0, F(1)=1
    a, b = 0, 1
    for _ in range(k):
        a, b = b, a + b
    return a


def _ref_prime_fib(n: int) -> int:
    count = 0
    k = 0
    while True:
        f = _ref_fib(k)
        if _ref_is_prime(f):
            count += 1
            if count == n:
                return f
        k += 1


# Precomputed, cross-checked with reference model for small n.
# F3=2, F4=3, F5=5, F7=13, F11=89, F13=233, F17=1597, F23=28657, F29=514229, F43=433494437
EXPECTED_1_TO_10 = [2, 3, 5, 13, 89, 233, 1597, 28657, 514229, 433494437]


def _ref_fib_set(limit: int):
    s = set()
    k = 0
    while True:
        f = _ref_fib(k)
        if f > limit:
            break
        s.add(f)
        k += 1
    return s


# ---- explicit example tests for every concrete example in the spec ----

def test_spec_example_1():
    assert prime_fib(1) == 2


def test_spec_example_2():
    assert prime_fib(2) == 3


def test_spec_example_3():
    assert prime_fib(3) == 5


def test_spec_example_4():
    assert prime_fib(4) == 13


def test_spec_example_5():
    assert prime_fib(5) == 89


# ---- known values beyond spec (reference cross-check, bounded to stay fast) ----

def test_known_values_1_to_10():
    for i, expected in enumerate(EXPECTED_1_TO_10, start=1):
        assert prime_fib(i) == expected


def test_equivalence_to_reference_model_1_to_7():
    # independent re-implementation agrees on small n
    for n in range(1, 8):
        assert prime_fib(n) == _ref_prime_fib(n)


# ---- property-based tests (kept to n<=5 so each call is cheap) ----

@given(st.integers(min_value=1, max_value=5))
def test_property_result_is_prime(n):
    assert _ref_is_prime(prime_fib(n))


@given(st.integers(min_value=1, max_value=5))
def test_property_result_is_fibonacci(n):
    v = prime_fib(n)
    assert v in _ref_fib_set(v)


@given(st.integers(min_value=1, max_value=5))
def test_property_result_type_is_int(n):
    v = prime_fib(n)
    assert type(v) == int


@given(st.integers(min_value=1, max_value=4))
def test_property_strictly_increasing(n):
    assert prime_fib(n + 1) > prime_fib(n)


@given(st.integers(min_value=1, max_value=5))
def test_property_nth_means_exactly_n_prime_fibs_at_or_below(n):
    v = prime_fib(n)
    # count prime fibs <= v using reference enumeration; must equal n
    count = 0
    k = 0
    while True:
        f = _ref_fib(k)
        if f > v:
            break
        if _ref_is_prime(f):
            count += 1
        k += 1
    assert count == n


@given(st.integers(min_value=1, max_value=4))
def test_property_no_prime_fib_skipped_between_successors(n):
    lo = prime_fib(n)
    hi = prime_fib(n + 1)
    # there must be no Fibonacci prime strictly between lo and hi
    k = 0
    while True:
        f = _ref_fib(k)
        if f > hi:
            break
        if lo < f < hi:
            assert not _ref_is_prime(f), f"skipped prime fib {f} between {lo} and {hi}"
        k += 1


@given(st.integers(min_value=1, max_value=5))
def test_property_idempotent_stable(n):
    assert prime_fib(n) == prime_fib(n)
